import SwiftUI

// MARK: - App entry

/// SunbayCheckout mock example app (SwiftUI, iOS).
///
/// A real Xcode app (generated by Tuist) that consumes only the SDK's public API plus the public
/// `SunbayCheckoutTestSupport` doubles. `DemoRootView` is a configuration playground that maps its knobs
/// into a `CheckoutConfiguration` + scripted mock services and drives `PaymentSheet` / `ApplePayButton`
/// end-to-end. Imports no internal SDK types and does not use `@testable`.
@main
struct SunbayCheckoutDemoApp: App {
    var body: some Scene {
        WindowGroup {
            DemoRootView()
        }
    }
}
